const D45 = [
{ id:'rogan-josh', c:'as', lat:34.084, lon:74.797, base:6, prep:30, cook:105, diff:2, tags:['lamb','slow','sunday'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f1a3a','#c9402c','#e0913a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Rogan josh',en:'Rogan josh'},
  p:{fr:'Srinagar, Cachemire, Inde',en:'Srinagar, Kashmir, India'},
  d:{fr:"Un curry d'agneau d'un rouge profond obtenu sans piment fort, par les seuls piments doux du Cachemire et la fleur de coquelicot. Il ne contient ni oignon ni ail dans sa version brahmane du Cachemire.",
     en:"A deep red lamb curry made without hot chilli, coloured only by mild Kashmiri chillies and cockscomb flower. In its Kashmiri Brahmin version it contains neither onion nor garlic."},
  i:[['lamb_shoulder',1.2,'kg'],['plain_yogurt',400,'g'],['kashmiri_chili',3,'tbsp'],['ginger',3,'tbsp'],['fennel',2,'tbsp'],['cardamom',6,'pc'],['cloves',6,'pc'],['cinnamon',2,'pc'],['bay_leaf',3,'pc'],['asafoetida',1,'pinch'],['ghee',120,'g'],['saffron',1,'pinch'],['basmati_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites chauffer le ghee et infusez-y les épices entières — cardamome, clous, cannelle, laurier — jusqu'à ce qu'elles chantent.","Ajoutez l'asafœtida, puis la viande en gros cubes, et faites-la saisir à feu vif sans la remuer trop souvent.","Incorporez le piment du Cachemire hors du feu : c'est lui qui donne la couleur, et il brûlerait à feu vif.","Ajoutez le yaourt battu cuillère par cuillère, en remuant sans arrêt : versé d'un coup, il tournerait.","Ajoutez le gingembre et le fenouil en poudre, couvrez et laissez mijoter 1 h 30 à feu doux. Finissez au safran infusé."],
     en:["Heat the ghee and infuse the whole spices in it — cardamom, cloves, cinnamon, bay — until they sing.","Add the asafoetida, then the meat in large cubes, and sear it over high heat without stirring too often.","Stir in the Kashmiri chilli off the heat: it provides the colour, and would scorch over a high flame.","Add the beaten yogurt a spoonful at a time, stirring constantly: tipped in at once it would split.","Add the ground ginger and fennel, cover and simmer for 1½ hours over low heat. Finish with infused saffron."]} },

{ id:'vindaloo-goanais', c:'as', lat:15.299, lon:74.124, base:6, prep:30, cook:90, diff:2, tags:['pork','spicy','slow'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f1a3a','#c9402c','#6f2a2a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Vindaloo de Goa',en:'Goan vindaloo'},
  p:{fr:'Panaji, Goa, Inde',en:'Panaji, Goa, India'},
  d:{fr:"Le descendant direct de la carne de vinha d'alhos portugaise, où le vinaigre de palme a remplacé le vin et où les piments se sont invités. Le nom n'a rien à voir avec la pomme de terre : aloo est une fausse piste.",
     en:"The direct descendant of Portuguese carne de vinha d'alhos, in which palm vinegar replaced wine and chillies invited themselves. The name has nothing to do with potato: aloo is a false trail."},
  i:[['pork_belly',1.2,'kg'],['kashmiri_chili',10,'pc'],['cane_vinegar',150,'ml'],['garlic',15,'clove'],['ginger',50,'g'],['cumin',2,'tsp'],['cloves',8,'pc'],['cinnamon',1,'pc'],['black_peppercorns',1,'tbsp'],['tamarind_paste',2,'tbsp'],['brown_sugar',2,'tbsp'],['onion',3,'pc'],['peanut_oil',100,'ml'],['basmati_rice',400,'g'],['salt',null,'']],
  s:{fr:["Faites tremper les piments séchés 30 minutes dans le vinaigre de canne tiède.","Mixez-les avec l'ail, le gingembre, le cumin, les clous, la cannelle et le poivre, en une pâte lisse — sans eau, seulement du vinaigre.","Faites mariner le porc en cubes 12 heures dans cette pâte, au frais.","Faites blondir l'oignon émincé dans l'huile, puis ajoutez la viande et sa marinade, et faites-la saisir 10 minutes.","Ajoutez le tamarin, le sucre et un verre d'eau, couvrez et laissez mijoter 1 h 15. Le plat est meilleur le lendemain."],
     en:["Soak the dried chillies for 30 minutes in warm cane vinegar.","Blend them with the garlic, ginger, cumin, cloves, cinnamon and pepper into a smooth paste — no water, only vinegar.","Marinate the diced pork in this paste for 12 hours in the fridge.","Fry the sliced onion golden in the oil, then add the meat and its marinade, and sear for 10 minutes.","Add the tamarind, sugar and a glass of water, cover and simmer for 1¼ hours. The dish is better the next day."]} },

{ id:'chettinad-kozhi', c:'as', lat:10.163, lon:78.795, base:4, prep:35, cook:50, diff:2, tags:['poultry','spicy','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f3b2a','#e0913a','#f0d8a8'],garnish:'#7fae6a'},
  n:{fr:'Poulet chettinad',en:'Chettinad chicken'},
  p:{fr:'Karaikudi, Tamil Nadu, Inde',en:'Karaikudi, Tamil Nadu, India'},
  d:{fr:"Le curry le plus épicé du Tamil Nadu, à la pierre de fleur et à la noix de coco grillée. Les Chettiars étaient des marchands qui commerçaient jusqu'en Birmanie : leur cuisine a rapporté des épices que le reste de l'Inde ignore.",
     en:"The most heavily spiced curry of Tamil Nadu, with stone flower and roasted coconut. The Chettiars were merchants trading as far as Burma: their cooking brought back spices the rest of India does not use."},
  i:[['chicken',1.2,'kg'],['coconut',150,'g'],['dried_chili',8,'pc'],['coriander_seeds',2,'tbsp'],['fennel',1,'tbsp'],['black_peppercorns',1,'tbsp'],['star_anise',2,'pc'],['stone_flower',1,'tbsp'],['curry_leaves',20,'pc'],['shallot',10,'pc'],['ginger_garlic_paste',3,'tbsp'],['ripe_tomato',300,'g'],['sesame_oil',100,'ml'],['turmeric',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites griller à sec la noix de coco râpée, les piments, la coriandre, le fenouil, le poivre, la badiane et la pierre de fleur, séparément, jusqu'à ce que chacun embaume.","Laissez refroidir avant de moudre : moulues chaudes, les épices deviennent amères.","Faites revenir les échalotes entières et les feuilles de curry dans l'huile de sésame, puis ajoutez la pâte gingembre-ail.","Ajoutez le poulet en morceaux, le curcuma et la tomate, et laissez saisir 10 minutes.","Incorporez la poudre d'épices, mouillez d'un verre d'eau et laissez mijoter 30 minutes : la sauce doit enrober la viande, pas la noyer."],
     en:["Dry-roast the grated coconut, chillies, coriander, fennel, pepper, star anise and stone flower separately, until each becomes fragrant.","Let them cool before grinding: ground hot, spices turn bitter.","Fry the whole shallots and curry leaves in the sesame oil, then add the ginger-garlic paste.","Add the jointed chicken, turmeric and tomato, and sear for 10 minutes.","Stir in the spice powder, add a glass of water and simmer for 30 minutes: the sauce should coat the meat, not drown it."]} },

{ id:'undhiyu', c:'as', lat:21.170, lon:72.831, base:8, prep:60, cook:90, diff:3, tags:['veg','festive','slow'],
  art:{v:'pot',bg:'#28331f',plate:'#f0e4c8',style:'stew',food:['#4f6f3a','#7fae5a','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Undhiyu',en:'Undhiyu'},
  p:{fr:'Surat, Gujarat, Inde',en:'Surat, Gujarat, India'},
  d:{fr:"Un ragoût de tous les légumes d'hiver, cuit à l'origine dans une jarre de terre retournée et enterrée sous un feu. Undhu veut dire « à l'envers » : le plat porte le nom de sa méthode de cuisson disparue.",
     en:"A stew of every winter vegetable, originally cooked in an earthenware pot turned upside down and buried under a fire. Undhu means 'upside down': the dish is named after its vanished cooking method."},
  i:[['sweet_potato',300,'g'],['eggplant',300,'g'],['potato',300,'g'],['broad_beans',300,'g'],['flat_green_beans',300,'g'],['chickpea_flour',200,'g'],['cilantro',2,'bunch'],['coconut',100,'g'],['green_chili',6,'pc'],['ginger',50,'g'],['carom_seeds',1,'tsp'],['sugar',2,'tbsp'],['peanut_oil',150,'ml'],['asafoetida',1,'pinch'],['turmeric',1,'tsp'],['salt',null,'']],
  s:{fr:["Préparez la farce verte : mixez coriandre, noix de coco, piments verts, gingembre, sucre et sel en une pâte épaisse.","Fendez les aubergines et les pommes de terre en croix sans les séparer, et remplissez-les de cette farce.","Préparez les muthia : mêlez la farine de pois chiche, un peu de farce, l'ajowan et l'eau, formez des boudins et faites-les frire.","Faites chauffer l'huile avec l'asafœtida, ajoutez les légumes durs d'abord, les tendres ensuite, sans jamais remuer à la cuillère.","Couvrez et laissez cuire 50 minutes à feu très doux, en secouant la marmite. Ajoutez les muthia et le reste de farce dix minutes avant la fin."],
     en:["Make the green filling: blend coriander, coconut, green chillies, ginger, sugar and salt into a thick paste.","Slit the aubergines and potatoes crosswise without separating them, and stuff them with this paste.","Make the muthia: mix the chickpea flour, a little of the paste, carom seeds and water, shape into logs and fry them.","Heat the oil with the asafoetida, add the hard vegetables first and the tender ones after, never stirring with a spoon.","Cover and cook for 50 minutes over very low heat, shaking the pot. Add the muthia and remaining paste ten minutes before the end."]} },

{ id:'litti-chokha', c:'as', lat:25.612, lon:85.144, base:6, prep:60, cook:45, diff:2, tags:['veg','street','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'flat',food:['#c9a878','#8f6a4a','#6f4a5a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Litti chokha',en:'Litti chokha'},
  p:{fr:'Patna, Bihar, Inde',en:'Patna, Bihar, India'},
  d:{fr:"Des boules de blé farcies de farine de pois chiche grillée, cuites dans la braise et trempées dans le ghee, servies avec une purée d'aubergine fumée. Le plat des champs du Bihar, cuisiné sans casserole ni huile.",
     en:"Wheat balls stuffed with roasted gram flour, baked in embers and dipped in ghee, served with a smoked aubergine mash. The field food of Bihar, cooked without a pan or a drop of oil."},
  i:[['whole_wheat_flour',500,'g'],['chickpea_flour',300,'g'],['ghee',150,'g'],['ginger',40,'g'],['garlic',8,'clove'],['green_chili',4,'pc'],['mustard_oil',60,'ml'],['carom_seeds',1,'tsp'],['lemon',2,'pc'],['eggplant',600,'g'],['ripe_tomato',400,'g'],['potato',400,'g'],['cilantro',1,'bunch'],['onion',2,'pc'],['salt',null,'']],
  s:{fr:["Pétrissez la farine complète, un peu de ghee, du sel et de l'eau en une pâte ferme ; laissez reposer 30 minutes.","Faites griller la farine de pois chiche à sec jusqu'à ce qu'elle brunisse, puis mêlez-la à l'ail, au gingembre, aux piments, à l'ajowan, au citron et à l'huile de moutarde.","Formez des boules de pâte, creusez-les, garnissez de deux cuillerées de farce et refermez soigneusement.","Cuisez-les 25 minutes dans la braise en les retournant, jusqu'à ce que la croûte noircisse par endroits ; ou 40 minutes au four à 200 °C.","Faites griller aubergines, tomates et pommes de terre à la flamme, pelez-les et écrasez-les avec oignon, coriandre et huile de moutarde. Trempez les litti dans le ghee fondu."],
     en:["Knead the wholemeal flour, a little ghee, salt and water into a firm dough; rest for 30 minutes.","Dry-roast the gram flour until it browns, then mix it with garlic, ginger, chillies, carom seeds, lemon and mustard oil.","Shape balls of dough, hollow them, fill with two spoonfuls of the mixture and seal carefully.","Cook them for 25 minutes in embers, turning, until the crust blackens in places; or 40 minutes in an oven at 200°C.","Char the aubergines, tomatoes and potatoes over a flame, peel and mash them with onion, coriander and mustard oil. Dip the litti in melted ghee."]} },

{ id:'khao-soi', c:'as', lat:18.788, lon:98.985, base:4, prep:30, cook:45, diff:2, tags:['noodles','poultry','comfort'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'noodle',food:['#e0913a','#c9402c','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Khao soi',en:'Khao soi'},
  p:{fr:'Chiang Mai, Thaïlande',en:'Chiang Mai, Thailand'},
  d:{fr:"Un curry de coco aux nouilles d'œuf, couronné des mêmes nouilles frites. Venu de Birmanie par les caravanes musulmanes du Yunnan, il porte encore la trace de cette route dans son curcuma et sa cardamome.",
     en:"A coconut curry with egg noodles, crowned with the same noodles fried crisp. It came from Burma with Yunnanese Muslim caravans, and still bears the mark of that route in its turmeric and cardamom."},
  i:[['chicken_thighs',800,'g'],['wheat_noodles',400,'g'],['coconut_milk',800,'ml'],['curry_powder',2,'tbsp'],['turmeric',1,'tsp'],['dried_chili',6,'pc'],['shallot',6,'pc'],['garlic',8,'clove'],['ginger',40,'g'],['lemongrass',2,'pc'],['fish_sauce',3,'tbsp'],['palm_sugar',1,'tbsp'],['lime',3,'pc'],['pickled_beans',150,'g'],['frying_oil',500,'ml'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites tremper les piments, puis pilez-les avec échalote, ail, gingembre et citronnelle en une pâte fine.","Faites réduire la crème épaisse du dessus de la boîte de coco jusqu'à ce que l'huile se sépare, puis faites-y frire la pâte 5 minutes.","Ajoutez le curry et le curcuma, puis le poulet, et laissez-le s'enrober avant de verser le reste du lait de coco.","Laissez mijoter 30 minutes, assaisonnez de sauce poisson, de sucre de palme et de citron vert.","Faites frire un quart des nouilles jusqu'à ce qu'elles gonflent. Dressez les nouilles bouillies, le curry, puis les nouilles frites, avec échalote crue et haricots marinés."],
     en:["Soak the chillies, then pound them with shallot, garlic, ginger and lemongrass into a fine paste.","Reduce the thick cream from the top of the coconut tin until the oil separates, then fry the paste in it for 5 minutes.","Add the curry powder and turmeric, then the chicken, and let it coat before pouring in the rest of the coconut milk.","Simmer for 30 minutes, and season with fish sauce, palm sugar and lime.","Deep-fry a quarter of the noodles until they puff. Plate the boiled noodles, the curry, then the fried noodles, with raw shallot and pickled greens."]} },

{ id:'massaman-curry', c:'as', lat:7.008, lon:100.475, base:6, prep:35, cook:90, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#e0913a','#f0e8d0','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Curry massaman',en:'Massaman curry'},
  p:{fr:'Songkhla, Thaïlande',en:'Songkhla, Thailand'},
  d:{fr:"Un curry doux aux épices sèches — cannelle, cardamome, clou de girofle — apporté par les marchands persans du XVIIe siècle. Le nom vient de « musulman » : c'est le seul curry thaï qui ne pique presque pas.",
     en:"A mild curry of dry spices — cinnamon, cardamom, clove — brought by 17th-century Persian traders. The name comes from 'Musulman': it is the only Thai curry that is barely hot at all."},
  i:[['beef_chuck',1.2,'kg'],['coconut_milk',800,'ml'],['dried_chili',6,'pc'],['shallot',8,'pc'],['garlic',10,'clove'],['lemongrass',3,'pc'],['galangal',40,'g'],['cinnamon',2,'pc'],['cardamom',6,'pc'],['cloves',6,'pc'],['peanuts',150,'g'],['potato',500,'g'],['tamarind_paste',3,'tbsp'],['palm_sugar',3,'tbsp'],['fish_sauce',4,'tbsp'],['salt',null,'']],
  s:{fr:["Faites griller à sec la cannelle, la cardamome et les clous, puis moulez-les avec les piments trempés, l'échalote, l'ail, la citronnelle et le galanga.","Faites réduire la crème de coco jusqu'à ce que l'huile perle, puis faites-y frire la pâte 8 minutes : c'est cette étape qui construit tout le goût.","Ajoutez le bœuf en gros cubes et laissez-le s'enrober, puis versez le reste du lait de coco.","Laissez mijoter 1 heure à couvert, puis ajoutez pommes de terre et cacahuètes pour 25 minutes.","Assaisonnez au tamarin, au sucre de palme et à la sauce poisson : le curry doit être à la fois sucré, salé et acide."],
     en:["Dry-roast the cinnamon, cardamom and cloves, then grind them with the soaked chillies, shallot, garlic, lemongrass and galangal.","Reduce the coconut cream until the oil beads, then fry the paste in it for 8 minutes: this step builds the whole flavour.","Add the beef in large cubes and let it coat, then pour in the rest of the coconut milk.","Simmer covered for 1 hour, then add the potatoes and peanuts for 25 minutes.","Season with tamarind, palm sugar and fish sauce: the curry should be sweet, salty and sour at once."]} },

{ id:'bun-bo-hue', c:'as', lat:16.463, lon:107.585, base:6, prep:45, cook:180, diff:3, tags:['noodles','spicy','soup'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'noodle',food:['#c9402c','#8f3b2a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Bún bò Huế',en:'Bún bò Huế'},
  p:{fr:'Huế, Viêt Nam',en:'Huế, Vietnam'},
  d:{fr:"La soupe de nouilles de l'ancienne capitale impériale, plus relevée et plus parfumée que le phở, à la citronnelle et à la pâte de crevette fermentée. Les nouilles y sont rondes, jamais plates : c'est la marque de Huế.",
     en:"The noodle soup of the old imperial capital, hotter and more fragrant than phở, with lemongrass and fermented shrimp paste. The noodles are round, never flat: the mark of Huế."},
  i:[['beef_shank',1,'kg'],['beef_bones',1,'kg'],['pork_knuckle',800,'g'],['rice_vermicelli',500,'g'],['lemongrass',6,'pc'],['shrimp_paste',2,'tbsp'],['chili_oil',4,'tbsp'],['fish_sauce',80,'ml'],['palm_sugar',2,'tbsp'],['onion',2,'pc'],['ginger',60,'g'],['bean_sprouts',300,'g'],['banana_flower',1,'pc'],['thai_basil',1,'bunch'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Blanchissez os, jarret et jambonneau 10 minutes, puis rincez-les soigneusement : c'est ce qui donne un bouillon limpide.","Grillez l'oignon et le gingembre entiers à la flamme jusqu'à noircir, puis mettez-les au bouillon avec la citronnelle écrasée.","Laissez frémir 3 heures sans jamais bouillir, en écumant régulièrement.","Délayez la pâte de crevette dans un peu de bouillon, laissez décanter et ne versez que le liquide clair : les impuretés troubleraient la soupe.","Assaisonnez de sauce poisson et de sucre, ajoutez l'huile pimentée à la citronnelle. Servez sur les vermicelles ronds, avec germes, fleur de bananier et herbes."],
     en:["Blanch the bones, shank and knuckle for 10 minutes, then rinse them thoroughly: this is what gives a clear broth.","Char the whole onion and ginger over a flame until blackened, then add them to the broth with the bruised lemongrass.","Simmer for 3 hours without ever boiling, skimming regularly.","Slake the shrimp paste in a little broth, let it settle and pour in only the clear liquid: the sediment would cloud the soup.","Season with fish sauce and sugar, and add the lemongrass chilli oil. Serve over round vermicelli, with sprouts, banana flower and herbs."]} },

{ id:'cao-lau', c:'as', lat:15.880, lon:108.338, base:4, prep:40, cook:120, diff:3, tags:['noodles','pork','comfort'],
  art:{v:'bowl',bg:'#2f3328',plate:'#f0e4c8',style:'noodle',food:['#c9a878','#8f5a3a','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Cao lầu',en:'Cao lầu'},
  p:{fr:'Hội An, Viêt Nam',en:'Hội An, Vietnam'},
  d:{fr:"Des nouilles épaisses et fermes, du porc laqué et très peu de bouillon. La tradition veut que les vraies nouilles soient faites avec l'eau d'un puits Cham précis de Hội An et de la cendre de bois de l'île de Cham.",
     en:"Thick firm noodles, lacquered pork and very little broth. Tradition holds that true noodles are made with water from one specific Cham well in Hội An and wood ash from the Cham Islands."},
  i:[['thick_rice_noodles',400,'g'],['pork_shoulder',600,'g'],['soy_sauce',60,'ml'],['five_spice',2,'tsp'],['garlic',8,'clove'],['shallot',4,'pc'],['bean_sprouts',200,'g'],['thai_basil',1,'bunch'],['cilantro',1,'bunch'],['rice_crackers',8,'pc'],['fish_sauce',3,'tbsp'],['palm_sugar',2,'tbsp'],['pork_bones',500,'g'],['chili_pepper',2,'pc'],['salt',null,'']],
  s:{fr:["Faites mariner le porc 4 heures dans la sauce soja, le cinq-épices, l'ail et l'échalote.","Faites-le rôtir 45 minutes en l'arrosant, puis laissez-le refroidir avant de le trancher très finement.","Faites un bouillon court avec les os et les sucs de cuisson : il n'en faut que trois cuillerées par bol, pas davantage.","Blanchissez les germes de soja et les nouilles séparément — les nouilles doivent rester fermes sous la dent, presque croquantes.","Dressez germes, nouilles, porc, herbes et crackers de riz croustillants, puis arrosez de bouillon assaisonné. Chacun mélange."],
     en:["Marinate the pork for 4 hours in the soy sauce, five spice, garlic and shallot.","Roast it for 45 minutes, basting, then cool it before slicing it very thinly.","Make a short broth with the bones and roasting juices: only three spoonfuls per bowl are needed, no more.","Blanch the bean sprouts and noodles separately — the noodles must stay firm to the bite, almost crunchy.","Layer sprouts, noodles, pork, herbs and crisp rice crackers, then spoon over the seasoned broth. Each diner mixes."]} },

{ id:'soto-betawi', c:'as', lat:-6.175, lon:106.827, base:6, prep:35, cook:120, diff:2, tags:['beef','soup','comfort'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e0b45a','#c9754a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Soto Betawi',en:'Soto Betawi'},
  p:{fr:'Jakarta, Indonésie',en:'Jakarta, Indonesia'},
  d:{fr:"Une soupe de bœuf et d'abats au lait de coco et au lait de vache, spécialité des Betawi, peuple métis de Batavia. L'usage des deux laits est une signature : le coco pour le gras, la vache pour la douceur.",
     en:"A soup of beef and offal with both coconut milk and cow's milk, the speciality of the Betawi, the mixed people of Batavia. Using both milks is a signature: coconut for the fat, cow for the sweetness."},
  i:[['beef_brisket',800,'g'],['beef_tripe',300,'g'],['coconut_milk',500,'ml'],['whole_milk',400,'ml'],['shallot',10,'pc'],['garlic',8,'clove'],['candlenut',6,'pc'],['ginger',40,'g'],['galangal',40,'g'],['lemongrass',3,'pc'],['kaffir_lime_leaves',6,'pc'],['cumin',1,'tsp'],['coriander_seeds',1,'tbsp'],['potato',400,'g'],['tomato',2,'pc'],['fried_onions',80,'g'],['lime',3,'pc'],['salt',null,'']],
  s:{fr:["Faites cuire la poitrine et les tripes 1 h 30 dans l'eau avec la citronnelle et le galanga, puis retirez-les et détaillez-les en dés.","Filtrez le bouillon et gardez-le.","Pilez échalote, ail, noix de bancoul, gingembre, cumin et coriandre en une pâte fine, et faites-la revenir jusqu'à ce qu'elle embaume.","Versez-la dans le bouillon avec les feuilles de combava, puis ajoutez le lait de coco et le lait de vache.","Laissez frémir 20 minutes sans bouillir, remettez la viande, et servez avec pommes de terre frites, tomate, oignons frits et citron vert."],
     en:["Cook the brisket and tripe for 1½ hours in water with the lemongrass and galangal, then lift them out and dice them.","Strain the broth and keep it.","Pound the shallot, garlic, candlenuts, ginger, cumin and coriander into a fine paste, and fry it until fragrant.","Stir it into the broth with the kaffir lime leaves, then add the coconut milk and the cow's milk.","Simmer for 20 minutes without boiling, return the meat, and serve with fried potato, tomato, fried shallots and lime."]} },

{ id:'babi-guling', c:'as', lat:-8.507, lon:115.262, base:10, prep:90, cook:240, diff:3, tags:['pork','festive','slow'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'grill',food:['#8f5a2b','#c9754a','#3a2a1a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Babi guling',en:'Babi guling'},
  p:{fr:'Ubud, Bali, Indonésie',en:'Ubud, Bali, Indonesia'},
  d:{fr:"Un cochon de lait farci d'une pâte d'épices et rôti à la broche quatre heures, jusqu'à ce que la peau devienne du verre. Plat de cérémonie hindoue à Bali, seule île indonésienne où le porc n'est pas interdit.",
     en:"A suckling pig stuffed with spice paste and spit-roasted for four hours, until the skin turns to glass. A Hindu ceremonial dish in Bali, the only Indonesian island where pork is not forbidden."},
  i:[['suckling_pig',6,'kg'],['shallot',20,'pc'],['garlic',20,'clove'],['turmeric',80,'g'],['ginger',80,'g'],['galangal',80,'g'],['candlenut',10,'pc'],['coriander_seeds',2,'tbsp'],['bird_eye_chili',10,'pc'],['lemongrass',6,'pc'],['kaffir_lime_leaves',10,'pc'],['shrimp_paste',2,'tbsp'],['peanut_oil',150,'ml'],['coconut_milk',200,'ml'],['cassava_leaves',500,'g'],['salt',null,'']],
  s:{fr:["Pilez au mortier tous les aromates en une pâte épaisse — le base gede balinais — et faites-la revenir 20 minutes à l'huile.","Frottez l'intérieur du cochon de la moitié de la pâte, farcissez-le de feuilles de manioc mêlées au reste, et cousez l'ouverture.","Frottez la peau de curcuma et d'eau salée, et laissez-la sécher deux heures à l'air.","Embrochez et rôtissez au-dessus d'un feu doux 4 heures, en tournant sans interruption et en badigeonnant d'eau de coco.","Montez le feu les vingt dernières minutes : la peau doit cloquer et devenir cassante comme du verre."],
     en:["Pound all the aromatics in a mortar into a thick paste — the Balinese base gede — and fry it in oil for 20 minutes.","Rub the inside of the pig with half the paste, stuff it with cassava leaves mixed with the rest, and sew the opening.","Rub the skin with turmeric and salted water, and let it dry in the air for two hours.","Spit it and roast over a low fire for 4 hours, turning continuously and basting with coconut water.","Raise the heat for the final twenty minutes: the skin should blister and turn brittle as glass."]} },

{ id:'kare-kare', c:'as', lat:14.599, lon:120.984, base:6, prep:40, cook:180, diff:2, tags:['beef','slow','comfort'],
  art:{v:'pot',bg:'#33291f',plate:'#f0e4c8',style:'stew',food:['#e0913a','#c9924a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kare-kare',en:'Kare-kare'},
  p:{fr:'Manille, Philippines',en:'Manila, Philippines'},
  d:{fr:"Une queue de bœuf dans une sauce épaisse de cacahuètes et de riz grillé, jaune de rocou. On la sert obligatoirement avec du bagoong, cette pâte de crevette fermentée qui apporte tout le sel : le ragoût lui-même n'en contient pas.",
     en:"Oxtail in a thick sauce of peanuts and toasted rice, yellow with annatto. It is served without fail with bagoong, the fermented shrimp paste that provides all the salt: the stew itself contains none."},
  i:[['oxtail',1.5,'kg'],['beef_tripe',400,'g'],['peanut_butter',250,'g'],['long_grain_rice',80,'g'],['achiote_paste',2,'tbsp'],['onion',2,'pc'],['garlic',8,'clove'],['eggplant',300,'g'],['flat_green_beans',300,'g'],['bok_choy',300,'g'],['banana_flower',200,'g'],['shrimp_paste',6,'tbsp'],['peanut_oil',80,'ml'],['salt',null,'']],
  s:{fr:["Faites cuire la queue de bœuf et les tripes 2 h 30 dans l'eau, jusqu'à ce que la viande quitte l'os ; gardez le bouillon.","Faites griller le riz cru à sec jusqu'à ce qu'il brunisse, puis moulez-le finement : c'est lui qui épaissira la sauce.","Faites revenir oignon et ail, ajoutez le rocou délayé, le beurre de cacahuète et deux litres de bouillon.","Incorporez la poudre de riz grillé et laissez épaissir 15 minutes en remuant.","Ajoutez les légumes par ordre de fermeté — haricots, aubergine, fleur de bananier, pak-choï — et la viande. Ne salez pas : le bagoong s'en charge à table."],
     en:["Cook the oxtail and tripe for 2½ hours in water, until the meat leaves the bone; keep the broth.","Dry-toast the raw rice until it browns, then grind it finely: this is what will thicken the sauce.","Fry the onion and garlic, add the slaked annatto, the peanut butter and two litres of broth.","Stir in the toasted rice powder and thicken for 15 minutes, stirring.","Add the vegetables in order of firmness — beans, aubergine, banana flower, pak choi — and the meat. Do not salt: the bagoong does that at the table."]} },

{ id:'nasi-lemak', c:'as', lat:3.139, lon:101.687, base:4, prep:40, cook:40, diff:2, tags:['rice','breakfast','spicy'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ecd8',style:'rice',food:['#f4f0e6','#c9402c','#e8c46a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Nasi lemak',en:'Nasi lemak'},
  p:{fr:'Kuala Lumpur, Malaisie',en:'Kuala Lumpur, Malaysia'},
  d:{fr:"Du riz cuit au lait de coco et au pandan, servi dans une feuille de bananier avec sambal, anchois frits, cacahuètes, concombre et œuf. C'est le petit-déjeuner national malaisien, vendu au coin des rues dès six heures.",
     en:"Rice cooked in coconut milk and pandan, served in a banana leaf with sambal, fried anchovies, peanuts, cucumber and egg. Malaysia's national breakfast, sold on street corners from six in the morning."},
  i:[['long_grain_rice',400,'g'],['coconut_milk',400,'ml'],['pandan_leaves',3,'pc'],['ginger',30,'g'],['dried_chili',15,'pc'],['shallot',10,'pc'],['garlic',6,'clove'],['shrimp_paste',1,'tbsp'],['tamarind_paste',2,'tbsp'],['palm_sugar',3,'tbsp'],['dried_fish',100,'g'],['peanuts',150,'g'],['egg',4,'pc'],['cucumber',1,'pc'],['banana_leaf',4,'pc'],['peanut_oil',150,'ml'],['salt',null,'']],
  s:{fr:["Rincez le riz jusqu'à ce que l'eau soit claire, puis cuisez-le dans le lait de coco allongé d'eau, avec le pandan noué et le gingembre.","Pour le sambal : faites tremper les piments, pilez-les avec échalote, ail et pâte de crevette.","Faites frire cette pâte 20 minutes à feu doux, jusqu'à ce que l'huile se sépare et remonte, rouge et brillante.","Ajoutez le tamarin et le sucre de palme, et laissez confire encore 10 minutes.","Faites frire les anchois séchés et les cacahuètes séparément. Dressez le riz dans une feuille de bananier avec sambal, anchois, cacahuètes, concombre et demi-œuf dur."],
     en:["Rinse the rice until the water runs clear, then cook it in coconut milk let down with water, with the knotted pandan and ginger.","For the sambal: soak the chillies, then pound them with shallot, garlic and shrimp paste.","Fry this paste for 20 minutes over low heat, until the oil separates and rises, red and glossy.","Add the tamarind and palm sugar, and cook down for another 10 minutes.","Fry the dried anchovies and peanuts separately. Serve the rice in a banana leaf with sambal, anchovies, peanuts, cucumber and half a hard-boiled egg."]} },

{ id:'ohn-no-khao-swe', c:'as', lat:16.871, lon:96.199, base:4, prep:35, cook:45, diff:2, tags:['noodles','poultry','soup'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'noodle',food:['#e8c46a','#e0913a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Ohn no khao swè',en:'Ohn no khao swè'},
  p:{fr:'Rangoun, Birmanie',en:'Yangon, Myanmar'},
  d:{fr:"Des nouilles de blé dans un bouillon de poulet au lait de coco, lié à la farine de pois chiche. Le cousin birman du khao soi, en plus doux : c'est le déjeuner de rue de Rangoun, servi avec un quartier de citron vert.",
     en:"Wheat noodles in a chicken and coconut broth thickened with chickpea flour. The Burmese cousin of khao soi, gentler: it is Yangon's street lunch, served with a wedge of lime."},
  i:[['chicken_thighs',700,'g'],['wheat_noodles',400,'g'],['coconut_milk',600,'ml'],['chickpea_flour',60,'g'],['onion',3,'pc'],['garlic',8,'clove'],['ginger',40,'g'],['turmeric',1,'tsp'],['paprika',1,'tbsp'],['fish_sauce',3,'tbsp'],['egg',4,'pc'],['cilantro',1,'bunch'],['lime',3,'pc'],['peanut_oil',100,'ml'],['chili_flakes',1,'tsp'],['salt',null,'']],
  s:{fr:["Mixez oignon, ail et gingembre en pâte, et faites-la revenir 15 minutes à l'huile avec le curcuma.","Ajoutez le poulet en morceaux et laissez-le s'enrober, puis mouillez d'un litre d'eau et laissez cuire 25 minutes.","Délayez la farine de pois chiche dans un peu d'eau froide, sans grumeau, et versez-la en filet dans le bouillon en remuant.","Ajoutez le lait de coco et laissez frémir 10 minutes : la soupe doit napper la cuillère.","Servez sur les nouilles avec un œuf dur coupé en deux, de la coriandre, de l'oignon frit, du citron vert et de l'huile pimentée."],
     en:["Blend the onion, garlic and ginger into a paste, and fry it in the oil for 15 minutes with the turmeric.","Add the jointed chicken and let it coat, then pour in a litre of water and cook for 25 minutes.","Slake the chickpea flour in a little cold water, lump-free, and trickle it into the broth while stirring.","Add the coconut milk and simmer for 10 minutes: the soup should coat the spoon.","Serve over the noodles with a halved hard-boiled egg, coriander, fried onion, lime and chilli oil."]} },

{ id:'lok-lak', c:'as', lat:11.556, lon:104.928, base:4, prep:25, cook:15, diff:1, tags:['beef','fast','fresh'],
  art:{v:'plate',bg:'#33251c',plate:'#f2e8d0',style:'grill',food:['#6f4a2a','#c9402c','#7fae5a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Bœuf lok lak',en:'Beef lok lak'},
  p:{fr:'Phnom Penh, Cambodge',en:'Phnom Penh, Cambodia'},
  d:{fr:"Des dés de bœuf sautés très vite, servis sur une salade avec une sauce au poivre de Kampot et au citron vert. Le poivre de Kampot fut, avant la guerre, le plus cher du monde : les tables parisiennes ne juraient que par lui.",
     en:"Cubes of beef seared very fast, served over salad with a Kampot pepper and lime sauce. Before the war Kampot pepper was the most expensive in the world: Paris tables swore by nothing else."},
  i:[['beef_sirloin',700,'g'],['soy_sauce',4,'tbsp'],['oyster_sauce',2,'tbsp'],['garlic',6,'clove'],['brown_sugar',2,'tbsp'],['black_peppercorns',2,'tbsp'],['lime',4,'pc'],['lettuce',1,'pc'],['ripe_tomato',3,'pc'],['cucumber',1,'pc'],['red_onion',1,'pc'],['egg',4,'pc'],['peanut_oil',60,'ml'],['long_grain_rice',400,'g'],['salt',null,'']],
  s:{fr:["Taillez le bœuf en cubes de 2 cm et faites-le mariner 30 minutes dans la sauce soja, l'huître, l'ail et le sucre.","Concassez le poivre grossièrement au mortier et mêlez-le au jus de citron vert et au sel : c'est la sauce tuk meric, servie à part.","Disposez la salade, les tomates, le concombre et l'oignon rouge en couronne dans les assiettes.","Saisissez le bœuf dans une poêle brûlante, par petites quantités, 90 secondes en tout : il doit rester rosé.","Posez la viande sur la salade, couronnez d'un œuf au plat et servez avec le riz et la sauce au poivre."],
     en:["Cut the beef into 2 cm cubes and marinate for 30 minutes in the soy, oyster sauce, garlic and sugar.","Crack the pepper coarsely in a mortar and mix it with lime juice and salt: this is the tuk meric sauce, served on the side.","Arrange the lettuce, tomato, cucumber and red onion in a ring on the plates.","Sear the beef in a scorching pan, in small batches, for 90 seconds in all: it should stay pink.","Set the meat on the salad, crown with a fried egg and serve with rice and the pepper sauce."]} },

{ id:'lamprais', c:'as', lat:6.927, lon:79.861, base:6, prep:90, cook:60, diff:3, tags:['rice','festive','bake'],
  art:{v:'leaf',bg:'#28331f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#8f5a3a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Lamprais',en:'Lamprais'},
  p:{fr:'Colombo, Sri Lanka',en:'Colombo, Sri Lanka'},
  d:{fr:"Un riz cuit au bouillon, trois viandes en curry, une aubergine confite et une boulette de crevette, le tout plié dans une feuille de bananier et repassé au four. Héritage des Burghers hollandais : le nom vient de lomprijst, « riz en paquet ».",
     en:"Rice cooked in stock, three meats in curry, a candied aubergine and a shrimp rissole, all folded into a banana leaf and returned to the oven. A Dutch Burgher legacy: the name comes from lomprijst, 'packet rice'."},
  i:[['long_grain_rice',500,'g'],['beef_chuck',300,'g'],['pork_shoulder',300,'g'],['lamb_shoulder',300,'g'],['cardamom',6,'pc'],['cloves',6,'pc'],['cinnamon',2,'pc'],['curry_powder',2,'tbsp'],['coconut_milk',400,'ml'],['eggplant',400,'g'],['shrimp',200,'g'],['onion',3,'pc'],['ghee',120,'g'],['banana_leaf',6,'pc'],['dried_chili',6,'pc'],['tamarind_paste',2,'tbsp'],['sugar',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites un bouillon avec les trois viandes, la cardamome, les clous et la cannelle ; réservez viandes et bouillon séparément.","Faites revenir le riz dans le ghee avec les épices entières, puis cuisez-le dans le bouillon filtré, jamais dans l'eau.","Coupez les viandes en dés et faites-les mijoter au curry et au lait de coco jusqu'à ce que la sauce soit courte.","Faites frire l'aubergine en tranches et confisez-la au tamarin, au sucre et aux piments : c'est le brinjal moju.","Passez les feuilles de bananier à la flamme pour les assouplir, garnissez de riz et des accompagnements, pliez en paquet et enfournez 25 minutes à 180 °C."],
     en:["Make a stock with the three meats, cardamom, cloves and cinnamon; set the meats and stock aside separately.","Fry the rice in ghee with the whole spices, then cook it in the strained stock, never in water.","Dice the meats and simmer them in curry and coconut milk until the sauce is short.","Fry the aubergine in slices and candy it with tamarind, sugar and chillies: this is brinjal moju.","Pass the banana leaves over a flame to soften them, fill with rice and the accompaniments, fold into parcels and bake for 25 minutes at 180°C."]} },

{ id:'dal-bhat-tarkari', c:'as', lat:27.717, lon:85.324, base:4, prep:30, cook:60, diff:1, tags:['legume','veg','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'rice',food:['#e8c46a','#f4f0e6','#7fae5a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Dal bhat tarkari',en:'Dal bhat tarkari'},
  p:{fr:'Katmandou, Népal',en:'Kathmandu, Nepal'},
  d:{fr:"Riz, lentilles et légumes de saison servis ensemble sur un plateau, deux fois par jour, toute une vie. Les porteurs de l'Himalaya en ont fait un dicton : « dal bhat power, twenty-four hour ».",
     en:"Rice, lentils and seasonal vegetables served together on a tray, twice a day, for a lifetime. Himalayan porters made a saying of it: 'dal bhat power, twenty-four hour'."},
  i:[['yellow_lentils',300,'g'],['long_grain_rice',400,'g'],['potato',400,'g'],['cauliflower',300,'g'],['green_beans',200,'g'],['ghee',80,'g'],['cumin',2,'tsp'],['turmeric',2,'tsp'],['fenugreek_seeds',1,'tsp'],['garlic',8,'clove'],['ginger',40,'g'],['dried_chili',3,'pc'],['ripe_tomato',200,'g'],['cilantro',1,'bunch'],['plain_yogurt',200,'g'],['salt',null,'']],
  s:{fr:["Rincez les lentilles et faites-les cuire 30 minutes avec le curcuma, jusqu'à ce qu'elles se défassent complètement.","Préparez le jhaneko, le tempérage : faites chanter dans le ghee brûlant le fenugrec, le cumin, l'ail, le gingembre et les piments séchés.","Versez ce beurre parfumé dans le dal — il grésille violemment — et couvrez aussitôt une minute pour retenir les arômes.","Pour le tarkari, faites revenir les légumes avec les mêmes épices et un peu de tomate, à couvert, 20 minutes.","Servez le riz au centre du plateau, le dal dans un bol, le tarkari à côté, avec du yaourt et un pickle."],
     en:["Rinse the lentils and cook them for 30 minutes with the turmeric, until they collapse completely.","Prepare the jhaneko, the tempering: sizzle the fenugreek, cumin, garlic, ginger and dried chillies in scorching ghee.","Pour this fragrant butter into the dal — it spits violently — and cover at once for a minute to trap the aromas.","For the tarkari, fry the vegetables with the same spices and a little tomato, covered, for 20 minutes.","Serve the rice in the centre of the tray, the dal in a bowl, the tarkari alongside, with yogurt and a pickle."]} },

{ id:'panch-phoron-torkari', c:'as', lat:23.810, lon:90.412, base:4, prep:25, cook:35, diff:1, tags:['veg','comfort','fast'],
  art:{v:'pot',bg:'#33301f',plate:'#f0e4c8',style:'stew',food:['#e0913a','#7fae5a','#e8c46a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Torkari aux cinq épices',en:'Five-spice torkari'},
  p:{fr:'Dacca, Bangladesh',en:'Dhaka, Bangladesh'},
  d:{fr:"Un ragoût de légumes au panch phoron, ce mélange bengali de cinq graines entières que l'on ne moud jamais. Nigelle, fenouil, fenugrec, cumin et moutarde : cinq saveurs qui se révèlent l'une après l'autre dans l'huile chaude.",
     en:"A vegetable stew with panch phoron, the Bengali blend of five whole seeds that is never ground. Nigella, fennel, fenugreek, cumin and mustard: five flavours that reveal themselves one after another in hot oil."},
  i:[['potato',400,'g'],['eggplant',300,'g'],['pumpkin',300,'g'],['flat_green_beans',200,'g'],['panch_phoron',2,'tbsp'],['mustard_oil',80,'ml'],['turmeric',1,'tsp'],['green_chili',4,'pc'],['ginger',40,'g'],['bay_leaf',2,'pc'],['sugar',1,'tsp'],['long_grain_rice',400,'g'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Faites fumer l'huile de moutarde puis laissez-la retomber : crue, elle est âcre ; fumée, elle devient douce.","Jetez-y le panch phoron entier et le laurier, et attendez que les graines de moutarde éclatent — pas avant, pas après.","Ajoutez le gingembre râpé et les piments fendus, puis les légumes en gros morceaux, du plus ferme au plus tendre.","Saupoudrez de curcuma, salez, sucrez d'une pincée, et couvrez : les légumes cuisent dans leur propre eau, sans en ajouter.","Laissez 25 minutes à feu doux en secouant la casserole, et couvrez de coriandre hors du feu."],
     en:["Heat the mustard oil until it smokes then let it settle: raw it is acrid; smoked it turns sweet.","Drop in the whole panch phoron and the bay, and wait for the mustard seeds to pop — not before, not after.","Add the grated ginger and split chillies, then the vegetables in large pieces, firmest first.","Dust with turmeric, salt, add a pinch of sugar, and cover: the vegetables cook in their own water, with none added.","Give them 25 minutes over low heat, shaking the pan, and cover with coriander off the heat."]} },

{ id:'shivit-oshi', c:'as', lat:41.378, lon:60.364, base:6, prep:60, cook:40, diff:3, tags:['noodles','veg','festive'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ecd8',style:'noodle',food:['#7fae5a','#4f8f4a','#e8dcb8','#c9754a'],garnish:'#6fbf8f'},
  n:{fr:'Chivit ochi',en:'Shivit oshi'},
  p:{fr:'Khiva, Khorezm, Ouzbékistan',en:'Khiva, Khorezm, Uzbekistan'},
  d:{fr:"Des nouilles d'un vert profond, colorées au jus d'aneth pétri dans la pâte, sous un ragoût de légumes et de viande. On ne les trouve qu'à Khiva et dans les villages autour : ailleurs en Ouzbékistan, personne ne les connaît.",
     en:"Deep green noodles, coloured by dill juice kneaded into the dough, under a stew of vegetables and meat. They are found only in Khiva and the villages around it: elsewhere in Uzbekistan nobody knows them."},
  i:[['flour',600,'g'],['dill',4,'bunch'],['egg',2,'pc'],['beef_chuck',500,'g'],['potato',500,'g'],['carrot',3,'pc'],['onion',2,'pc'],['ripe_tomato',400,'g'],['red_pepper',2,'pc'],['garlic',6,'clove'],['cumin',1,'tbsp'],['sunflower_oil',100,'ml'],['plain_yogurt',300,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Mixez l'aneth avec un verre d'eau et pressez à travers un linge : c'est ce jus vert, et lui seul, qui colore la pâte.","Pétrissez la farine, les œufs, le sel et le jus d'aneth 15 minutes ; laissez reposer une heure.","Étalez très finement, roulez et taillez des nouilles de 2 mm, puis farinez-les généreusement.","Faites saisir la viande en dés, ajoutez oignon, carotte, poivron, tomate, ail et cumin, mouillez à hauteur et laissez mijoter 40 minutes avec les pommes de terre.","Cuisez les nouilles 3 minutes, dressez-les en nid et couronnez du ragoût. Servez le yaourt à part."],
     en:["Blend the dill with a glass of water and press it through a cloth: it is this green juice, and nothing else, that colours the dough.","Knead the flour, eggs, salt and dill juice for 15 minutes; rest for an hour.","Roll very thin, fold and cut 2 mm noodles, then flour them generously.","Sear the diced meat, add onion, carrot, pepper, tomato, garlic and cumin, cover with water and simmer for 40 minutes with the potatoes.","Cook the noodles for 3 minutes, arrange them in a nest and crown with the stew. Serve the yogurt alongside."]} },

{ id:'kuurdak', c:'as', lat:42.874, lon:74.570, base:6, prep:30, cook:90, diff:1, tags:['lamb','comfort','slow'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#c9754a','#e8dcb8','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Kuurdak',en:'Kuurdak'},
  p:{fr:'Bichkek, Kirghizistan',en:'Bishkek, Kyrgyzstan'},
  d:{fr:"Un sauté de mouton et d'abats aux oignons et aux pommes de terre, cuit dans le kazan de fonte. C'était le premier plat préparé après l'abattage d'une bête, avec les morceaux qui ne se conservaient pas.",
     en:"A fry-up of mutton and offal with onions and potatoes, cooked in a cast-iron kazan. It was the first dish made after slaughtering an animal, with the cuts that would not keep."},
  i:[['mutton_shoulder',800,'g'],['lamb_kidney',300,'g'],['lamb_fat',150,'g'],['onion',600,'g'],['potato',600,'g'],['cumin',2,'tsp'],['black_peppercorns',1,'tbsp'],['bay_leaf',2,'pc'],['cilantro',1,'bunch'],['flatbread',6,'pc'],['salt',null,'']],
  s:{fr:["Faites fondre le gras de mouton en dés dans le kazan jusqu'à ce qu'il ne reste que des grattons, et retirez-les.","Saisissez la viande en gros cubes dans cette graisse, à feu vif, sans la remuer trop tôt : elle doit brunir.","Ajoutez les abats parés, puis les oignons émincés — beaucoup, autant que de viande — et laissez-les fondre 20 minutes.","Ajoutez le cumin, le poivre concassé et le laurier, couvrez et laissez mijoter 40 minutes dans le seul jus rendu.","Ajoutez les pommes de terre en gros morceaux pour les 25 dernières minutes, et servez avec du pain plat et de la coriandre."],
     en:["Render the diced mutton fat in the kazan until only scratchings remain, and lift them out.","Sear the meat in large cubes in that fat over high heat, without stirring too soon: it must brown.","Add the trimmed offal, then the sliced onions — a great many, as much as there is meat — and let them melt for 20 minutes.","Add the cumin, cracked pepper and bay, cover and simmer for 40 minutes in nothing but the released juices.","Add the potatoes in large pieces for the last 25 minutes, and serve with flatbread and coriander."]} },

{ id:'chelo-kabab-barg', c:'as', lat:32.657, lon:51.668, base:4, prep:40, cook:20, diff:2, tags:['beef','grill','festive'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'skewer',food:['#8f3b2a','#f4f0e6','#e8c46a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Kabab barg et riz au safran',en:'Kabab barg with saffron rice'},
  p:{fr:'Ispahan, Iran',en:'Isfahan, Iran'},
  d:{fr:"Des lamelles de filet marinées à l'oignon et au safran, grillées sur des brochettes plates, servies avec un riz croustillant au fond de la casserole. Ce tahdig doré est disputé à table plus que la viande elle-même.",
     en:"Slices of fillet marinated in onion and saffron, grilled on flat skewers, served with rice crisped at the bottom of the pan. That golden tahdig is fought over at the table more than the meat itself."},
  i:[['beef_sirloin',800,'g'],['onion',3,'pc'],['saffron',1,'tsp'],['plain_yogurt',150,'g'],['lemon',2,'pc'],['basmati_rice',500,'g'],['butter',150,'g'],['sumac',2,'tbsp'],['ripe_tomato',4,'pc'],['flatbread',4,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les oignons et pressez-en le jus ; mêlez-le au safran infusé, au yaourt et au citron, et faites mariner la viande 12 heures.","Rincez le riz sept fois puis faites-le tremper 2 heures dans l'eau salée : c'est ce qui donne des grains longs et détachés.","Précuisez-le 6 minutes à grande eau, égouttez, puis remettez-le en dôme dans une casserole beurrée avec du safran.","Couvrez d'un linge et d'un couvercle et laissez cuire 45 minutes à feu très doux : une croûte dorée se forme au fond.","Enfilez la viande sur des brochettes plates et grillez-la 3 minutes par face sur braise vive. Servez avec le riz, le tahdig, la tomate grillée et le sumac."],
     en:["Grate the onions and press out their juice; mix it with infused saffron, yogurt and lemon, and marinate the meat for 12 hours.","Rinse the rice seven times then soak it for 2 hours in salted water: this is what gives long separate grains.","Par-boil it for 6 minutes in plenty of water, drain, then mound it in a buttered pan with saffron.","Cover with a cloth and a lid and cook for 45 minutes over very low heat: a golden crust forms at the bottom.","Thread the meat onto flat skewers and grill for 3 minutes a side over fierce embers. Serve with the rice, the tahdig, grilled tomato and sumac."]} },

{ id:'maqluba', c:'as', lat:31.905, lon:35.204, base:6, prep:45, cook:75, diff:2, tags:['rice','festive','poultry'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0913a','#6f4a5a','#f0e8d0','#e8c46a'],garnish:'#7fae6a'},
  n:{fr:'Maqluba',en:'Maqluba'},
  p:{fr:'Naplouse, Palestine',en:'Nablus, Palestine'},
  d:{fr:"Un plat de riz, d'aubergines et de poulet monté en couches puis retourné d'un bloc sur un plateau. Maqluba veut dire « à l'envers » : le moment du renversement se fait en silence, et l'on applaudit s'il tient.",
     en:"A dish of rice, aubergine and chicken built in layers then turned out in one piece onto a tray. Maqluba means 'upside down': the moment of inversion is done in silence, and applauded if it holds."},
  i:[['chicken',1.4,'kg'],['eggplant',700,'g'],['basmati_rice',500,'g'],['cauliflower',400,'g'],['onion',2,'pc'],['allspice',2,'tsp'],['cinnamon',1,'tsp'],['turmeric',1,'tsp'],['bay_leaf',3,'pc'],['cardamom',5,'pc'],['pine_nuts',60,'g'],['almonds',60,'g'],['frying_oil',700,'ml'],['plain_yogurt',300,'g'],['parsley',4,'tbsp'],['salt',null,'']],
  s:{fr:["Pochez le poulet 40 minutes avec oignon, laurier, cardamome et quatre-épices ; gardez le bouillon, qui cuira le riz.","Faites frire les tranches d'aubergine et les bouquets de chou-fleur jusqu'à ce qu'ils dorent, puis égouttez-les.","Faites tremper le riz 30 minutes, égouttez-le et mêlez-le aux épices moulues.","Tapissez le fond d'une marmite d'aubergines en rosace, puis le poulet désossé, le chou-fleur, et enfin le riz bien tassé.","Versez le bouillon chaud à deux centimètres au-dessus du riz, couvrez et cuisez 40 minutes. Laissez reposer 15 minutes avant de retourner d'un geste franc."],
     en:["Poach the chicken for 40 minutes with onion, bay, cardamom and allspice; keep the broth, which will cook the rice.","Fry the aubergine slices and cauliflower florets until golden, then drain them.","Soak the rice for 30 minutes, drain it and mix it with the ground spices.","Line the base of a pot with aubergine in a rosette, then the boned chicken, the cauliflower, and finally the rice, well packed.","Pour in hot broth to two centimetres above the rice, cover and cook for 40 minutes. Rest for 15 minutes before inverting in one decisive movement."]} },

{ id:'kibbeh-nayyeh', c:'as', lat:34.437, lon:35.830, base:6, prep:40, cook:0, diff:3, tags:['lamb','fresh','festive'],
  art:{v:'plate',bg:'#33251c',plate:'#f2e8d0',style:'salad',food:['#8f1a3a','#c9402c','#4f8f4a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Kibbeh nayyeh',en:'Kibbeh nayyeh'},
  p:{fr:'Tripoli, Liban',en:'Tripoli, Lebanon'},
  d:{fr:"De l'agneau cru pilé au mortier de pierre avec du boulgour fin et des épices, servi en tapis lisse sous un filet d'huile. Il se prépare le jour de l'abattage, et se mange dans l'heure : c'est la règle.",
     en:"Raw lamb pounded in a stone mortar with fine bulgur and spices, served as a smooth carpet under a thread of oil. It is made on the day of slaughter, and eaten within the hour: that is the rule."},
  i:[['lamb_leg',600,'g'],['bulgur',200,'g'],['onion',1,'pc'],['mint',1,'bunch'],['basil',1,'bunch'],['allspice',1,'tsp'],['cinnamon',1,'tsp'],['olive_oil',120,'ml'],['pita_bread',6,'pc'],['spring_onion',6,'pc'],['ice_water',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez un gigot d'agneau abattu le jour même, parez-le de tout gras et de tout nerf, et gardez-le glacé jusqu'au dernier moment.","Rincez le boulgour fin et pressez-le : il doit être humide mais non détrempé.","Pilez l'oignon et les épices au mortier jusqu'à obtenir une pâte, puis ajoutez la viande par petites quantités.","Pilez longuement en ajoutant le boulgour et quelques cuillerées d'eau glacée, jusqu'à obtenir une masse parfaitement lisse.","Étalez en couche mince sur un plateau, dessinez des sillons au doigt, arrosez d'huile d'olive et servez aussitôt avec menthe, oignons nouveaux et pain."],
     en:["Choose a leg of lamb slaughtered the same day, trim it of all fat and sinew, and keep it ice cold until the last moment.","Rinse the fine bulgur and squeeze it: it should be damp but not sodden.","Pound the onion and spices in a mortar into a paste, then add the meat in small amounts.","Pound at length, working in the bulgur and a few spoonfuls of iced water, until the mass is perfectly smooth.","Spread it thinly on a tray, draw furrows with your fingers, pour over olive oil and serve at once with mint, spring onions and bread."]} },

{ id:'ash-e-reshteh', c:'as', lat:35.699, lon:51.338, base:6, prep:40, cook:90, diff:2, tags:['legume','soup','veg'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'soup',food:['#4f6f3a','#7fae5a','#f4f0e6','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Ash-e reshteh',en:'Ash-e reshteh'},
  p:{fr:'Téhéran, Iran',en:'Tehran, Iran'},
  d:{fr:"Une soupe épaisse de légumineuses, d'herbes et de nouilles, garnie de kashk — un petit-lait séché et fermenté. On la prépare à Norouz, le nouvel an persan : les nouilles symbolisent les fils du destin que l'on démêle.",
     en:"A thick soup of pulses, herbs and noodles, finished with kashk — a dried fermented whey. Made for Nowruz, the Persian new year: the noodles stand for the threads of fate being untangled."},
  i:[['chickpeas',150,'g'],['red_kidney_beans',150,'g'],['brown_lentils',150,'g'],['wheat_noodles',250,'g'],['spinach',400,'g'],['parsley',2,'bunch'],['cilantro',2,'bunch'],['chives',2,'bunch'],['onion',4,'pc'],['garlic',10,'clove'],['turmeric',2,'tsp'],['dried_mint',2,'tbsp'],['kashk',200,'g'],['peanut_oil',120,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper pois chiches et haricots une nuit, puis cuisez-les 1 heure avec le curcuma et un oignon.","Ajoutez les lentilles et poursuivez 25 minutes.","Ciselez toutes les herbes très finement — elles doivent représenter un volume énorme, presque deux litres tassés — et ajoutez-les à la soupe.","Cassez les nouilles et jetez-les dans le bouillon pour 10 minutes ; remuez, car elles attachent facilement.","Préparez deux garnitures : oignons frits jusqu'au brun foncé, et menthe séchée frite dans l'huile avec l'ail. Servez avec le kashk en spirale."],
     en:["Soak the chickpeas and beans overnight, then cook them for 1 hour with the turmeric and one onion.","Add the lentils and continue for 25 minutes.","Chop all the herbs very finely — they should make an enormous volume, nearly two packed litres — and add them to the soup.","Break the noodles and drop them into the broth for 10 minutes; stir, as they catch easily.","Prepare two garnishes: onions fried to deep brown, and dried mint fried in oil with garlic. Serve with kashk swirled over."]} },

{ id:'khachapuri-megrelien', c:'as', lat:42.512, lon:41.870, base:6, prep:60, cook:25, diff:2, tags:['cheese','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ecd8',style:'flat',food:['#e0b45a','#f4f0e6','#f2dfa8','#c98a2c'],garnish:'#7fae6a'},
  n:{fr:'Khatchapouri mégrélien',en:'Megrelian khachapuri'},
  p:{fr:'Zougdidi, Mingrélie, Géorgie',en:'Zugdidi, Samegrelo, Georgia'},
  d:{fr:"Un pain rond au fromage, farci et recouvert de sulguni, contrairement à l'adjarien en forme de barque. La Mingrélie double la dose : le fromage est dedans et dessus, et personne ne s'en excuse.",
     en:"A round cheese bread, filled and also topped with sulguni, unlike the boat-shaped Adjarian version. Samegrelo doubles the dose: cheese inside and on top, and nobody apologises for it."},
  i:[['flour',500,'g'],['whole_milk',250,'ml'],['plain_yogurt',150,'g'],['dry_yeast',7,'g'],['sugar',1,'tbsp'],['sulguni_cheese',700,'g'],['egg',2,'pc'],['butter',100,'g'],['salt',null,'']],
  s:{fr:["Délayez la levure et le sucre dans le lait tiède, puis pétrissez avec la farine, le yaourt, un œuf, du beurre fondu et le sel.","Laissez lever 1 h 30 : la pâte doit être très souple, presque collante.","Râpez le sulguni et travaillez-en les deux tiers à la main jusqu'à ce qu'il devienne élastique.","Étalez la pâte en disque, déposez le fromage au centre, ramenez les bords vers le milieu et retournez la boule. Aplatissez délicatement au rouleau.","Dorez à l'œuf, couvrez du fromage restant et enfournez 20 minutes à 240 °C. Beurrez généreusement à la sortie."],
     en:["Dissolve the yeast and sugar in the warm milk, then knead with the flour, yogurt, one egg, melted butter and salt.","Prove for 1½ hours: the dough should be very supple, almost sticky.","Grate the sulguni and work two thirds of it by hand until it turns elastic.","Roll the dough into a disc, pile the cheese in the centre, gather the edges to the middle and turn the ball over. Flatten it gently with a rolling pin.","Glaze with egg, cover with the remaining cheese and bake for 20 minutes at 240°C. Butter it generously as it comes out."]} }
];
